def modpow(base, exponent, mod):
    if mod <= 0:
        raise ValueError('mod must be positive')
    result = 1
    base %= mod
    while exponent > 0:
        if exponent & 1:
            result = (result * base) % mod
        base = (base * base) % mod
        exponent >>= 1
    return result

