def sqrt_newton(x, tol=1e-10):
    if x < 0:
        raise ValueError('cannot take square root of a negative number')
    if x == 0:
        return 0.0
    guess = x / 2.0
    while True:
        new_guess = (guess + x / guess) / 2
        if abs(new_guess - guess) < tol:
            return new_guess
        guess = new_guess

print(sqrt_newton(2))

def is_perfect(n):
    if n < 2:
        return False
    total = 1
    d = 2
    while d * d <= n:
        if n % d == 0:
            total += d
            if d != n // d:
                total += n // d
        d += 1
    return total == n

print(is_perfect(496))

def roman_to_int(s):
    values = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    if not s or any(ch not in values for ch in s):
        raise ValueError('invalid Roman numeral')
    total = 0
    for i, ch in enumerate(s):
        total += values[ch]
        if i + 1 < len(s) and values[ch] < values[s[i + 1]]:
            total -= 2 * values[ch]
    return total

print(roman_to_int('MCMXCIV'))

