def n_choose_k(n, k):
    if k < 0 or k > n:
        return 0
    k = min(k, n - k)
    result = 1
    for i in range(k):
        result = result * (n - i) // (i + 1)
    return result

print(n_choose_k(52, 5))

def digit_count(n):
    if n < 0:
        n = -n
    if n == 0:
        return 1
    count = 0
    while n:
        count += 1
        n //= 10
    return count

